$db=new PDO(getenv('CM_TEST_DSN') ?: 'sqlite::memory:',getenv('CM_TEST_DB_USER') ?: null,getenv('CM_TEST_DB_PASSWORD') ?: null);$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);
$db->exec('CREATE TABLE orders (id VARCHAR(36) PRIMARY KEY, fingerprint VARCHAR(64) NOT NULL, created_at BIGINT NOT NULL, payload MEDIUMTEXT NOT NULL, mail_status VARCHAR(16) NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_attempt BIGINT NOT NULL, lease VARCHAR(64) NULL, lease_until BIGINT NOT NULL DEFAULT 0)');
$app=new Orders($c,$db);
$p=json_decode(file_get_contents(__DIR__.'/../backend/catalog.json'),true)[0];
